#!/bin/bash
# Field port: lean/fl/K/*.part (generated by port.py from the C parts) -> lean/fl/FLK_field.lean
L=/home/kevxhk/work/L-gct-210/leanfl; F=/home/kevxhk/work/L-gct-210/lean/fl
OLD="pre a b c d1 e f g h j k o2 p i5 l2 m n r1 r2 s1 s2 s3 t3 ds x1 x2 x3 y1 x4 n1 n2 z1 z2 q1 r4 r5 f1 g1 h1"
NEW="sc1a sc1b ps ps4 ps5 np3b ncolp prred pr3a pr3b ps6 pr3c pr3d pr3e ps2 ps3 np3c"
R6="lz lzp p51a p51b p51c p51d x5a"
R7="x5b tc5c x5c lagcore"
R8="lag nbcore nb p1 p1b p1c p2 nbl nbq"
R9="p3a p3b p3c p4a p4b"
R10="p4c p4d p4e p4f p4g p4h p4i p4j p4k"
R11="p5a p5b p5c p5d p5e p5f p5g p5h p5i p5j p5k p5l p5m p5n p5o p5p p5q p5r p5s p5t p5u p5v p5w p5x p5y p5z p5aa p5ab p5ac p5ad"
cd $L && rm -f portK.json && python3 -I port.py $F $F/K "$OLD $NEW $R6 $R7 $R8 $R9 $R10 $R11" portK.json > port_report.txt || exit 1
grep "MISMATCH" port_report.txt
cd $F/K && (for p in $OLD; do cat $p.part; done; cat w.tail) > $F/FLK_field.lean.new && (cmp -s $F/FLK_field.lean.new $F/FLK_field.lean && rm $F/FLK_field.lean.new || mv $F/FLK_field.lean.new $F/FLK_field.lean)
G=$F/FLK_field.lean
echo "$G: $(wc -lc < $G) add $(grep -cE '^[[:space:]]*add_' $G) quotes $(grep -c '"' $G) hash $(grep -c '#' $G) banned $(grep -cE 'sorry|axiom|native_decide|initialize|macro|syntax|notation|elab|attribute|instance|structure|inductive' $G) comments $(grep -cE -- '--|/-' $G) dupnames $(grep -E '^(theorem|def|abbrev|noncomputable def|@\[simp\] theorem) ' $G | sed 's/@\[simp\] //' | awk '{print $2}' | sort | uniq -d | wc -l) Complex $(grep -c Complex $G)"
# TC5 blocks (rounds 7-11) with the needed blocks of the earlier ported parts
python3 -I $L/closure.py $F/K "$OLD $NEW $R6" "$R7 $R8 $R9 $R10 $R11" $L/TrK11.lean.new && (cmp -s $L/TrK11.lean.new $L/TrK11.lean && rm $L/TrK11.lean.new || mv $L/TrK11.lean.new $L/TrK11.lean)
G=$L/TrK11.lean
echo "$G: $(wc -lc < $G) add $(grep -cE '^[[:space:]]*add_' $G) quotes $(grep -c '"' $G) hash $(grep -c '#' $G) banned $(grep -cE 'sorry|axiom|native_decide|initialize|macro|syntax|notation|elab|attribute|instance|structure|inductive' $G) comments $(grep -cE -- '--|/-' $G) dupnames $(grep -E '^(theorem|def|abbrev|noncomputable def|@\[simp\] theorem) ' $G | sed 's/@\[simp\] //' | awk '{print $2}' | sort | uniq -d | wc -l) Complex $(grep -c Complex $G)"
# smoke test: a few key blocks with their closure
python3 -I $L/closure_names.py $F/K "$OLD" "propR r3_inj r3_sums generic_pt A1 inj_succ5 IIa_tu roots5 Vp_finrank coeffs HypIIa_proof" $L/TrK0.lean.new && (cmp -s $L/TrK0.lean.new $L/TrK0.lean && rm $L/TrK0.lean.new || mv $L/TrK0.lean.new $L/TrK0.lean)
# split SL/FL test files (each self-contained closure of the ported FLk parts)
for spec in "SLa:SL_of" "SLb:HypS6_proof" "SLc:HypS7_of HypS7alg_of HypIIa_proof" "SLd:HypS8_proof" "FL:FL_of FL_col_of"; do
  nm=${spec%%:*}; tg=${spec#*:}
  python3 -I $L/closure_names.py $F/K "$OLD" "$tg" $L/FLK_$nm.lean.new > /dev/null && (cmp -s $L/FLK_$nm.lean.new $L/FLK_$nm.lean && rm $L/FLK_$nm.lean.new || mv $L/FLK_$nm.lean.new $L/FLK_$nm.lean)
  echo "FLK_$nm.lean: $(wc -l < $L/FLK_$nm.lean) lines"
done
python3 -I - <<'PY'
s=open('/home/kevxhk/work/L-gct-210/leanfl/TrK0.lean').read()
k=s.index('noncomputable section\n')+len('noncomputable section\n')
s=s[:k]+'\nset_option profiler true\n\nset_option profiler.threshold 300\n'+s[k:]
open('/home/kevxhk/work/L-gct-210/leanfl/TrK0p.lean.new','w').write(s)
import os
os.replace('/home/kevxhk/work/L-gct-210/leanfl/TrK0p.lean.new','/home/kevxhk/work/L-gct-210/leanfl/TrK0p.lean')
PY
